/*
 * build_stamp.cpp — the ONE translation unit that carries the build stamp.
 * [SPEC:CXC-BOARD-HW] — workstream 0.2/0.4 of
 * docs/PLAN-fleet-baseline-and-bus-native.md.
 *
 * It exists to be TINY and to be RECOMPILED EVERY BUILD.  Both properties are
 * the point; see the long note on cxc_build_fingerprint() in announce.h.
 *
 * Short version: `gen/build_stamp.h` is regenerated by
 * cyd/tools/gen_build_stamp.py on every `pio run`, so its content differs
 * every time and ninja rebuilds whatever includes it.  Confining that include
 * to a 40-line file means the cost of a never-stale build stamp is one small
 * compile, instead of recompiling main.cpp's ~1,200 lines and the whole
 * widget header set to move four bytes.
 *
 * DO NOT include gen/build_stamp.h anywhere else.
 */

#include "announce.h"

/* Generated per-env at build time.  If this include fails, the extra_script
 * did not run — check `extra_scripts` in cyd/platformio.ini.  A HARD FAILURE
 * is correct here: the silent alternative is a fleet in which every device
 * reports fingerprint 0, which makes the reflash campaign unverifiable while
 * looking perfectly healthy.  That is the exact failure shape this whole
 * workstream exists to remove. */
#include "gen/build_stamp.h"

uint32_t cxc_build_fingerprint(void) { return CXC_BUILD_FINGERPRINT; }

const char* cxc_build_stamp(void) { return CXC_BUILD_STAMP; }
